function validWorkspace(value){
 const strings=(v,keys)=>keys.every(key=>v[key]===undefined||typeof v[key]==='string');
 const validCover=p=>{try{validateCoverDesign(p.coverDesign);const bg=p.coverBackground;return bg===undefined||(bg&&typeof bg==='object'&&!Array.isArray(bg)&&typeof bg.src==='string'&&strings(bg,['alt','caption']));}catch{return false;}};
 const validProduction=p=>{try{if(p.production!==undefined)validateProductionData(p.production);return true;}catch{return false;}};
 const validSources=p=>{try{validatePublication(p.publication);validateRegisteredSources(p.registeredSources);validateReviewDesk(p.reviewDesk);validateSharedReviewSources(p.sharedReviewSources);validateCollaboration(p.collaboration);validateDocumentSource(p.documentSource);normalizeBookMatter(p.bookMatter,{chapterIds:p.chapters?.map(c=>c.id)||[],validateImage:v=>({src:validateImageSource(v.src),alt:String(v.alt||''),caption:String(v.caption||''),...(v.presentation===undefined?{}:{presentation:normalizeMediaPresentation(v.presentation)})}),validateFigures:validateChapterFigures});return true;}catch{return false;}};
 const validComputer=p=>{try{validateComputerResearch(p.computerResearch);p.chapters?.forEach(c=>validateChapterFigures(c?.figures));return true;}catch{return false;}};
 const validBook=p=>p&&typeof p==='object'&&typeof p.id==='string'&&p.id.length>0&&typeof p.title==='string'&&strings(p,['subtitle','author','description','language','theme','tone','voiceSample','audience','genre','updatedAt'])&&validProduction(p)&&validCover(p)&&validComputer(p)&&validSources(p)&&Array.isArray(p.chapters)&&p.chapters.length>0&&new Set(p.chapters.map(c=>c?.id)).size===p.chapters.length&&p.chapters.every(c=>c&&typeof c.id==='string'&&typeof c.title==='string'&&typeof c.content==='string');
 if(!value||!Array.isArray(value.projects)||!value.projects.length||!value.projects.every(validBook)||new Set(value.projects.map(p=>p.id)).size!==value.projects.length)return false;
 if(value.histories!==undefined&&(value.histories===null||typeof value.histories!=='object'||Array.isArray(value.histories)||!Object.values(value.histories).every(list=>Array.isArray(list)&&list.every(h=>h&&typeof h.id==='string'&&validBook(h.project)))))return false;
 return true;
}
function recoveryHTML(){return recoveryMessage?`<section class="notice warning storage-recovery" role="alert"><b>원고 보호를 위해 저장을 멈췄습니다.</b><p>${esc(recoveryMessage)}${initialRecovery?' 아래 샘플은 임시 화면이며 저장된 원고를 대체하지 않습니다.':''}</p><div class="inline-actions">${btn('현재 작업 전체 백업','backup-workspace','secondary','export')}${workspaceStore?.getRecoveryData()?btn('보관 데이터 받기','recover-storage','secondary','export'):''}${btn('다시 열기','reload-workspace','secondary','refresh')}</div></section>`:'';}
function updateRecovery(){const existing=$('.storage-recovery');if(existing)existing.remove();const main=$('.main');if(main&&recoveryMessage)main.insertAdjacentHTML('afterbegin',recoveryHTML());}
function handleStorageError(error){storageLocked=['CONFLICT','CORRUPT','READ_FAILED'].includes(error?.code);recoveryMessage=error?.message||'기기 저장에 실패했습니다. 현재 작업을 백업해 주세요.';saveStatus(storageLocked?'저장 중지 · 백업 필요':'저장 실패 · 백업 필요',true);updateRecovery();toast(recoveryMessage,true);}
function saveStatus(label,error=false){storageStatus=label;storageError=error;const el=$('#save-state');if(el)el.innerHTML=`<span class="save-dot" style="${error?'background:#bd806d':''}"></span>${esc(label)}`;}
function persist(immediate=false){
 if(!project())return Promise.resolve(false);
 project().updatedAt=new Date().toISOString();dirty=true;const seq=++saveSequence;clearTimeout(persistTimer);
 if(storageLocked){saveStatus('저장 중지 · 백업 필요',true);return Promise.resolve(false);}
 saveStatus('저장 중…');
 const doSave=()=>{const snapshot=clone(state);pendingSave=pendingSave.catch(()=>{}).then(()=>workspaceStore.write(snapshot)).then(()=>{if(seq===saveSequence){dirty=false;recoveryMessage='';saveStatus('이 기기에 저장됨');updateRecovery();}return true;}).catch(error=>{handleStorageError(error);return false;});return pendingSave;};
 if(immediate)return doSave();persistTimer=setTimeout(doSave,450);
}
function checkpoint(label,p=project()){const history=state.histories[p.id]||[];history.unshift({id:uid(),label,at:new Date().toISOString(),project:clone(p)});state.histories[p.id]=history.slice(0,8);}
function upgradeBook(p,recordHistory=false){const before=recordHistory?clone(p):null;const matterChanged=ensureBookMatter(p),captionsChanged=cleanDefaultIllustrationCaptions(p);if(recordHistory&&(matterChanged||captionsChanged))checkpoint('책 편집 기능 적용 전',before);return p;}
function replaceProject(next){upgradeBook(next);const i=state.projects.findIndex(p=>p.id===next.id);if(i>=0)state.projects[i]=next;else state.projects.push(next);state.activeId=next.id;activeChapterId=next.chapters[0]?.id;persist(true);}
const imageCache=new Map();
function safeImage(src){if(typeof src!=='string')return '';if(imageCache.has(src))return imageCache.get(src);let validated='';try{validated=validateImageSource(src);}catch{}if(imageCache.size>=24)imageCache.delete(imageCache.keys().next().value);if(src.length<=2000000)imageCache.set(src,validated);return validated;}
