async function readProductionSource(input,bundle=false) {
 const form=input.closest('form'),files=Array.from(input.files||[]);
 if(!files.length)return;
 cancelProductionSourceRead();
 const token=productionFileToken,controller=new AbortController();productionFileController=controller;
 productionFilePending=true;$('[type="submit"]',form).disabled=true;
 $('[data-action="production-source-cancel"]',form).hidden=false;
 $('#production-source-name').textContent='원시 자료를 읽는 중…';$('#production-feedback').hidden=true;
 const isCurrent=()=>token===productionFileToken&&form.isConnected&&$('#production-form')===form&&!busy;
 try {
  let raw,name,manifest,sourceImages,ignoredCount=0;
  if(bundle){
   const result=await readSourceFiles(files,{signal:controller.signal,onProgress:({completed,total,path})=>{
    if(isCurrent())$('#production-source-name').textContent=`${completed}/${total}개 읽기 · ${path}`;
   }});
   raw=result.sourceMarkdown;name=result.sourceName;
   if(result.files.length)manifest={files:result.files,ignoredCount:result.ignoredCount,folderName:result.folderName};
   sourceImages=result.sourceImages;ignoredCount=result.ignoredCount;
  }else{
   const file=files[0];
   if(!/\.(md|markdown|txt)$/i.test(file.name))throw new Error('Markdown(.md, .markdown) 또는 텍스트(.txt) 파일을 선택해 주세요.');
   if(file.size>480000)throw new Error('원시 자료는 120,000자까지 지원합니다. 파일을 나누어 주세요. 기존 자료는 유지했습니다.');
   const bytes=await file.arrayBuffer();
   raw=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes);
   if(raw.length>120000)throw new Error('원시 자료가 120,000자를 넘습니다. 내용을 자르지 않았습니다. 파일을 나누어 주세요.');
   name=file.name.slice(0,255);
  }
  controller.signal.throwIfAborted();if(!isCurrent())return;
  productionDraft.sourceMarkdown=raw;productionDraft.sourceName=name;
  if(manifest)productionDraft.sourceManifest=manifest;else delete productionDraft.sourceManifest;
  if(bundle){if(sourceImages?.length)productionDraft.sourceImages=sourceImages;else delete productionDraft.sourceImages;}
  $('#production-source').value=raw;refreshProductionSourceDisplay();$('#production-feedback').hidden=true;
  if(ignoredCount)productionFeedback(`자료를 반영했습니다. 지원하지 않는 파일 ${ignoredCount}개는 제외했습니다.`);
 }catch(error){if(isCurrent()&&error.name!=='AbortError'){
  productionFeedback(error instanceof TypeError?'UTF-8 텍스트 파일인지 확인해 주세요. 기존 자료는 유지했습니다.':error.message);
  refreshProductionSourceDisplay();
 }}finally{if(token===productionFileToken){productionFilePending=false;productionFileController=null;if(form.isConnected){$('[type="submit"]',form).disabled=false;$('[data-action="production-source-cancel"]',form).hidden=true;}input.value='';}}
}
