async function productionArtwork(p,signal,approval,retry=false) {
 const assertApproved=()=>assertProductionApproval(p,approval,getAIConfig(),{retry,running:true});
 const data=p.production,brief=data.brief;
 if(data.artwork?.status==='complete')return;
 data.artwork??={status:'pending',completed:[]};
 const artwork=data.artwork;artwork.status='running';delete artwork.error;
 try{
  signal.throwIfAborted();
  if(brief.illustrations!=='none'){
   const indexes=[0,Math.floor(p.chapters.length/2)].filter((n,i,a)=>a.indexOf(n)===i);
   if(brief.illustrations==='ai'&&!artwork.completed.includes('cover')){
    if(!p.coverImage){assertApproved();updateProgress('책의 주제에 맞는 표지를 생성합니다…');applyBookCover(p,await generateBookCover(p,{signal,onProgress:updateProgress}),{select:normalizeCoverDesign(p.coverDesign).source!=='background'});}
    artwork.completed.push('cover');await saveAIResult();
   }
   for(const i of indexes){
    signal.throwIfAborted();const key=`chapter:${i}`,c=p.chapters[i];if(artwork.completed.includes(key))continue;
    if(!c.image){updateProgress(`${i+1}장 · ${brief.illustrations==='ai'?'AI':'디자인'} 삽화 배치`);if(brief.illustrations==='ai'){assertApproved();c.image=await generateImage(`Editorial illustration, no text. Book topic: ${brief.topic.slice(0,1500)}. Chapter: ${c.title}. ${c.imagePrompt||c.content.slice(0,1200)}. Visual direction: ${brief.instructions.slice(0,2000)}.`,{signal});c.image.alt=`${c.title}의 내용을 표현한 삽화`;}else addArt(c);}
    artwork.completed.push(key);await saveAIResult();
   }
  }
  artwork.status='complete';await saveAIResult();
 }catch(error){artwork.status=error.name==='AbortError'?'paused':'failed';artwork.error=error.name==='AbortError'?'삽화 작업을 중지했습니다.':error.message;await saveAIResult();throw error;}
}
